from pathlib import Path
import json,shutil,html,re
R=Path(__file__).resolve().parents[1];D=R/'Defence'; S=[]
A=json.loads((R/'asset-manifest.json').read_text())
def L(s):return '<LaTeX formula="'+html.escape(s,quote=True)+'" />'
def plot(k,caption='',cls='plot-large',plain=False):return '<div class="'+cls+'"><Plot src="'+A[k]['display']+'" caption="'+html.escape(caption,quote=True)+'" '+('plain' if plain else '')+'/></div>'
def cols(a,b,kind=''):return '<div class="columns '+kind+'"><div>'+a+'</div><div>'+b+'</div></div>'
def take(s):return '<div class="takeaway">'+s+'</div>'
def add(slug,title,body,notes,sec=1,duration=60,source='',cls=''):
 S.append(dict(slug=slug,title=title,body=body,notes=notes,section=sec,seconds=duration,source=source,cls=cls))
def chapter(slug,title,scene,n,sub,notes):
 add(slug,title,f'<PhysicsScene scene="{scene}"/><div class="chapter-copy"><div class="chapter-number">{n:02d} / DISSERTATION DEFENCE</div><h1>{title}</h1><p>{sub}</p></div><ChapterRail :active="{n}"/><div class="scene-caption">'+('Conceptual cluster merger. Blue: collisionless mass.<br/>Rose: collisional gas.' if scene=='cluster' else 'Conceptual atomic view. Electron orbits are illustrative.' if scene=='atom' else 'DarkSHINE detector concept. Illustrative event trajectories.')+'</div>',notes,n,15,cls='section-slide no-page-number')
# Local images are copied byte-for-byte.
for key,f in [('bullet','DEF-218.jpg'),('rotation','DEF-230.png'),('cmb','DEF-241.jpg'),('facility','DEF-364.png')]:
 source=R.parent/'Refs/assets/refs/ZhiyuZhao_dessertation_defense_v8/media'/f
 if source.exists():shutil.copy2(source,D/'public/figures'/f)
 A[key]={'display':'figures/'+f,'source':'Refs/assets/refs/ZhiyuZhao_dessertation_defense_v8/media/'+f}
add('cover','Design of DarkSHINE Simulation Framework and Prospective Study of Positron-Beam Mode','''<BrandBar/><div class="cover-head"><div class="eyebrow">PhD Dissertation Defence</div><h1>Design of <span class="accent-title">DarkSHINE</span><br/>Simulation Framework<br/>and Prospective Study of<br/>Positron-Beam Mode</h1></div><div class="cover-details"><div><span>Candidate</span> Xuliang Zhu</div><div><span>Supervisor</span> Shu Li</div></div><div class="cover-date">10th Nov. 2026</div>''','Good afternoon, professors. I am Xuliang Zhu. My dissertation connects the development of the DarkSHINE simulation framework with a prospective search using a positron beam. I will first introduce the experimental motivation, then describe the software contributions, and finally discuss the detector-level analysis and its sensitivity.',0,30,cls='cover-slide no-page-number')
add('outline','Outline','''<div class="eyebrow">45-minute report</div><h1>Outline</h1><div class="outline-list"><div class="outline-row"><b>01</b><span>Physics motivation<br/>and DarkSHINE</span><em>~11 min</em></div><div class="outline-row"><b>02</b><span>Event simulation<br/>and reconstruction</span><em>~13 min</em></div><div class="outline-row"><b>03</b><span>Positron-beam-mode<br/>analysis</span><em>~17 min</em></div><div class="outline-row"><b>04</b><span>Summary and outlook</span><em>~3 min</em></div></div>''','The central question is how a rare missing-energy signal can be studied with a reliable and affordable simulation. The first part sets the detector requirements. The second explains how the framework turns these requirements into simulated and reconstructed events. The third combines three positron production mechanisms in exclusive reconstructed categories. I will keep theoretical details to the assumptions needed to interpret the experiment.',0,35,cls='outline-slide no-page-number')
chapter('physics','Physics Motivation and<br/>DarkSHINE Experiment','cluster',1,'Light dark matter and an accelerator-based missing-energy search','I begin with the physical motivation. The cluster animation illustrates why gravitational evidence motivates an unseen matter component, while the laboratory search still requires a specified interaction model.')
add('evidence','Evidence for dark matter',cols(plot('bullet','Bullet Cluster: lensing mass and hot gas have different spatial distributions.','plot-mid',True),'<h2 class="blue">Gravity across scales</h2><p>Galaxy rotation curves require extended mass distributions.</p><p>Cluster lensing traces mass beyond luminous matter.</p><p>CMB anisotropies require a non-baryonic matter component.</p><div class="statline"><div><b>~5 : 1</b><span>Dark matter to ordinary matter</span></div></div>')+take('The abundance is established gravitationally. The particle identity and laboratory couplings remain open.'),'The Bullet Cluster is a particularly useful example because the hot gas, which contains much of the ordinary matter, is spatially displaced from the gravitational mass inferred through lensing. Rotation curves and the CMB provide independent evidence on very different scales. The common conclusion is an additional gravitating component, roughly five times as abundant as baryonic matter. These observations do not determine a coupling to electrons or the mass of a new mediator. Those are the quantities an accelerator experiment can test within a benchmark interaction model.',duration=60,source='Clowe et al., ApJ 648 (2006) L109; Planck 2018. Image: supplied reference assets.')
add('properties','What observations constrain',cols('<h2 class="blue">Properties required by observations</h2><ul><li>Long-lived on cosmological time scales</li><li>Weak electromagnetic interactions</li><li>Sufficiently cold to form small structures</li><li>Self-interactions bounded by cluster dynamics</li></ul>','<h2 class="gold">Mass bounds depend on the model</h2><ul><li>Fermionic phase-space bounds</li><li>Free-streaming constraints for thermal relics</li><li>BBN and CMB constraints on light thermal species</li><li>Late annihilation depends on the final state and velocity scaling</li></ul>')+take('MeV–GeV dark matter remains a motivated experimental target under specified cosmological assumptions.'),'It is useful to distinguish general requirements from model-dependent numerical bounds. Dark matter must survive long enough and must not erase the observed small-scale structure. A phase-space bound applies to fermions, while a thermal free-streaming bound assumes a particular early velocity distribution. BBN and the CMB constrain new species in thermal contact with the Standard Model and any subsequent energy injection. These bounds motivate the light-dark-matter programme, but they should not be combined into a universal exclusion of every particle below one mass. For the remainder of the talk I use a vector-portal benchmark in the MeV to GeV range.',duration=60,source='Cosmological and particle constraints summarized in the dissertation; model assumptions retained.')
add('searches','Complementary dark-matter searches','''<div class="columns thirds"><div><div class="eyebrow">Galactic dark matter</div><h2 class="blue">Direct detection</h2><div class="formula-band">'''+L(r'\chi+T\to\chi+T')+'''</div><p class="small">Measure a recoil from halo dark matter.</p><p class="small muted">Depends on the local density and velocity distribution.</p></div><div><div class="eyebrow">Astrophysical products</div><h2 class="violet">Indirect detection</h2><div class="formula-band">'''+L(r'\chi\bar\chi\to\mathrm{SM}')+'''</div><p class="small">Search for annihilation or decay products.</p><p class="small muted">Depends on astrophysical distributions and backgrounds.</p></div><div><div class="eyebrow">Controlled production</div><h2 class="gold">Accelerators</h2><div class="formula-band">'''+L(r'\mathrm{SM}\to A^{\prime}\to\chi\bar\chi')+'''</div><p class="small">Produce an invisible state in a known initial state.</p><p class="small muted">Depends on production, exposure and detector acceptance.</p></div></div>'''+take('DarkSHINE measures missing energy and momentum in a controlled fixed-target interaction.'),'The three approaches probe complementary aspects of the interaction. Direct detection samples the existing Galactic population and becomes experimentally challenging when the recoil energy is very small. Indirect detection looks for products of annihilation or decay. An accelerator instead creates the state in a controlled collision. The known beam energy provides a reference, and a deficit in the measured visible energy becomes the observable. This interpretation does not require the local halo density, although relating the result to the cosmic abundance still requires a dark-sector model. The central experimental challenge is to reject ordinary interactions with unobserved visible particles.',duration=55)
add('portal','The dark photon as a vector portal','''<div class="formula-band" style="font-size:24px">'''+L(r'\mathcal L\supset-\frac{\epsilon}{2}F_{\mu\nu}F^{\prime\mu\nu}+\frac12m_{A^{\prime}}^2A^{\prime}_\mu A^{\prime\mu}')+'''</div><div class="columns"><div class="copy"><h2 class="blue">Kinetic mixing</h2><p>After diagonalising the kinetic terms, the mediator couples to the electromagnetic current:</p><div class="formula-band">'''+L(r'\mathcal L_{\mathrm{int}}\supset\epsilon e A^{\prime}_\mu J_{\mathrm{EM}}^\mu')+'''</div><p class="small">Production rates scale approximately as '''+L(r'\epsilon^2')+'''.</p></div><div class="copy"><h2 class="rose">Invisible benchmark</h2><p>Dark-sector coupling '''+L(r'g_D A^{\prime}_\mu J_D^\mu')+'''.</p><p>For '''+L(r'm_{A^{\prime}}>2m_\chi')+''', assume</p><div class="formula-band">'''+L(r'\mathrm{BR}(A^{\prime}\to\chi\bar\chi)\simeq1')+'''</div><p class="small">Experimental coordinates: '''+L(r'(m_{A^{\prime}},\epsilon^2)')+'''.</p></div></div>'''+take('A minimal benchmark connects a production rate to an experimentally measurable energy deficit.'),'This is the low-energy form of the kinetic-mixing interaction. The small parameter epsilon induces a coupling of the dark photon to the electromagnetic current. The mass controls the available kinematics, while epsilon squared approximately rescales the production rate. I assume that the mediator can decay to lighter dark-sector particles and that the invisible branching fraction is close to one. The projected limit is therefore presented first in mediator mass and kinetic mixing. Only later will I impose a mass ratio and dark coupling to compare with thermal relic targets. No detailed ultraviolet model is required for the detector-level study.',duration=70,source='Vector-portal benchmark and invisible-decay assumptions in the dissertation.')
add('shine','SHINE facility and DarkSHINE beamline',cols(plot('facility','SHINE superconducting linac and experimental halls.','plot-large'),'<h2 class="blue">A high-repetition-rate source</h2><p>Shanghai High Repetition-Rate XFEL and Extreme Light Facility</p><div class="statline"><div><b>8 GeV</b><span>Reference beam energy</span></div></div><div class="statline"><div><b>10 MHz</b><span>Nominal single-particle rate</span></div></div><p class="small" style="margin-top:20px">Exposure benchmark: '+L(r'3\times10^{14}')+' incident particles.</p>','wide')+take('A dedicated extraction branch provides the basis for the electron programme. Positron delivery is a prospective extension.'),'SHINE provides the accelerator setting for DarkSHINE. The electron programme uses a dedicated single-particle extraction branch alongside the FEL beamlines. I use the eight GeV reference beam energy and an exposure of three times ten to the fourteen incident particles. The nominal rate shown here is ten MHz, as adopted for this defence, rather than the one MHz value in the older text. At this rate the benchmark corresponds approximately to a full calendar year of continuous delivery. Actual running time and duty factor remain separate operational inputs. The positron analysis studies the physics benefit of an extension; it does not demonstrate an implemented positron beamline.',duration=55,source='SHINE layout: supplied collaboration assets. Rate updated to 10 MHz for this defence.')
add('detector','DarkSHINE detector concept','''<div style="height:245px;margin-top:-12px"><PhysicsScene compact labels/></div><div class="columns thirds" style="gap:28px;margin-top:-10px"><div><h2 class="blue">Tracking</h2><p class="small">Tag the incoming particle.<br/>Measure recoil momentum and multiplicity.</p></div><div><h2 class="mint">ECAL</h2><p class="small">Measure electromagnetic energy.<br/>Resolve localized deposits.</p></div><div><h2 class="violet">HCAL</h2><p class="small">Veto neutral hadrons and penetrating muons.</p></div></div>'''+take('A thin tungsten target links a known incident particle to a fully instrumented visible final state.'),'The detector follows the beam from left to right. The upstream tracker measures the incident momentum in the magnet. A thin tungsten target provides the interaction material, followed by the recoil tracker. The electromagnetic calorimeter measures the remaining electromagnetic energy, and the larger hadronic calorimeter rejects escaping hadrons and muons. The large HCAL volume is required to contain penetrating particles. The tracker uses strip measurements, and the ECAL uses a segmented crystal array. Their acceptance and response are evaluated with the configured simulation geometry.',duration=65,source='DarkSHINE collaboration detector concept and geometry.')
add('requirements','Detector requirements for a missing-energy search',cols('<table><tr><th>Subsystem</th><th>Experimental role</th></tr><tr><td class="blue">Tagging tracker</td><td>One incident track and a momentum reference</td></tr><tr><td class="rose">Tungsten target</td><td>'+L(r'0.1X_0\simeq350\,\mu\mathrm m')+'</td></tr><tr><td class="blue">Recoil tracker</td><td>Soft-track acceptance and multiplicity</td></tr><tr><td class="mint">LYSO ECAL</td><td>Contain electromagnetic showers</td></tr><tr><td class="violet">Fe/scintillator HCAL</td><td>Reject penetrating visible particles</td></tr></table>',plot('ecal-hardware','LYSO detector development by the DarkSHINE collaboration.','plot-mid',True)) +take('Tracking and calorimeter vetoes address different ways for ordinary events to imitate missing energy.'),'The detector requirements are tied to the background problem. A thin target limits multiple scattering while retaining sufficient production probability. Precise strip measurements determine the incident and recoil momenta. A soft recoil can curl in a strong field, so the recoil-field profile and acceptance matter together. The ECAL must measure the electromagnetic energy, and the HCAL must catch energy carried by neutral hadrons or muons. Hardware developments shown here are collaboration work. My contribution is the software framework and analysis that propagate the detector response into selected yields. In particular, a threshold used in the prospective analysis must be distinguished from a demonstrated system-level performance.',duration=60,source='DarkSHINE detector design and collaboration subsystem studies.')
add('baseline','Electron-mode signal and background rejection',cols('<FeynmanDiagram mode="brem" charge="-"/><div class="formula-band">'+L(r'e^-N\to e^-NA^{\prime},\quad A^{\prime}\to\chi\bar\chi')+'</div><p class="small">One soft recoil electron with substantial missing energy and momentum.</p>','<h2 class="gold">Measurements used together</h2><ul><li>Exactly one incident particle</li><li>A recoil carrying less momentum</li><li>Low electromagnetic energy</li><li>No significant hadronic or muon activity</li></ul><div class="rule"></div><p class="small muted">Hard bremsstrahlung is abundant. Rare photonuclear, electronuclear and muon-pair processes can leave poorly measured energy.</p>')+take('The sensitivity is controlled by the rare surviving tails of Standard Model interactions.'),'In the baseline electron mode, dark bremsstrahlung produces an invisible dark photon and a visible recoil electron. The recoil tends to carry only part of the original beam energy. Ordinary bremsstrahlung can create a similar soft electron, but the photon should deposit its energy in the ECAL. The dangerous cases are the rare subsequent processes that move this energy into hadrons or muons, or beyond acceptance. This motivates the joint use of momentum, ECAL energy and HCAL vetoes. It also explains why describing average electromagnetic showers is insufficient: the analysis is sensitive to the exceptionally small fraction that survives every requirement.',duration=65,source='J. Chen et al., Sci. China Phys. Mech. Astron. 66, 211062 (2023).')
add('background-hierarchy','Standard Model background hierarchy','<BackgroundRates/>'+take('Rare-process generation must preserve the hard-photon origin and the interaction location.'),'This diagram preserves the branching hierarchy of the supplied reference. Electronuclear interactions form one branch. Hard bremsstrahlung forms the other, followed by ordinary pair conversion, photonuclear interactions or conversion to muon pairs. Target and ECAL interactions are shown separately because they encounter different veto material and have different rates. The vertical scale is an approximate relative-rate hierarchy from the reference electron study, not the sample-normalisation table for the positron analysis. The extremely small invisible electroweak contribution is separated from the visible leakage backgrounds. The computational challenge is to sample the visible rare branches efficiently without losing their physical normalisation.',duration=55,source='DarkSHINE collaboration: electron-mode background hierarchy.')
add('why-positrons','Why a positron beam?', '''<div class="columns thirds diagram-columns"><div><h2 class="blue">Dark bremsstrahlung</h2><FeynmanDiagram mode="brem"/><div class="reaction">'''+L(r'e^+N\to e^+NA^{\prime}')+'''</div><p>A recoil positron remains.</p></div><div><h2 class="gold">Non-resonant annihilation</h2><FeynmanDiagram mode="radiative"/><div class="reaction">'''+L(r'e^+e^-\to\gamma A^{\prime}')+'''</div><p>A photon accompanies the invisible state.</p></div><div><h2 class="rose">Resonant annihilation</h2><FeynmanDiagram mode="resonant"/><div class="reaction">'''+L(r'e^+e^-\to A^{\prime}')+'''</div><p>Very little visible downstream activity.</p></div></div>'''+take(L(r'\sqrt{s}\simeq\sqrt{2m_eE_{e^+}}=90.4\,\mathrm{MeV}')+' for an 8 GeV beam and an electron initially at rest.'),'A positron keeps the nuclear bremsstrahlung process and adds annihilation on atomic electrons. The non-resonant process produces a photon together with the dark photon. Resonant annihilation can produce the dark photon without an accompanying visible hard particle. For an electron initially at rest, an eight GeV positron gives a centre-of-mass energy of about ninety MeV. This creates a characteristic mass scale that is absent from the electron bremsstrahlung channel. However, larger production rates alone do not establish an improvement. The visible topology, detector efficiency, migration and positron-specific backgrounds all have to be included. The following software section explains the infrastructure that makes that comparison possible.',duration=70,source='X. Zhu et al., arXiv:2609.05900. Radiative diagram shows one representative tree topology.')
chapter('software','Event Simulation and<br/>Reconstruction in DarkSHINE','detector',2,'A configurable chain for detector studies and rare-process production','The framework must connect the detector definition to the analysis while keeping rare-process production computationally manageable. This section presents my software contributions within the collaboration environment.')
add('workflow','The DarkSHINE software framework','<FlowDiagram kind="workflow"/>'+take('<span class="gold">Candidate-led:</span> DSimu, DEvent, rare-process biasing and filtering, and ACTS integration.'),'The workflow separates transport from reconstruction through ROOT event files. DSimu configures the detector and physics and records the simulated event. DEvent defines the shared collections. DAna applies digitisation, reconstruction and analysis processors in the configured order, and DDis provides event inspection. My work led DSimu, the event model, rare-process biasing and staged filtering, and the ACTS integration. DAna, digitisation, the other tracking algorithms, calorimeter reconstruction and generator-validation studies are collaboration contributions. A common event interface lets us follow one event through these stages and change downstream algorithms without repeating transport when the required information has been retained.',2,65,source='DSS software framework; X. Zhu, Nucl. Part. Phys. Proc. 346 (2024) 57.')
add('event-model','A common event model: DEvent','<FlowDiagram kind="model"/>'+take('Collection types distinguish Monte Carlo truth, detector deposits, response and reconstructed objects.'),'DEvent carries named collections with explicit roles. McParticle and DStep contain truth information. SimulatedHit records transport deposits, CalorimeterHit describes the detector response, and ReconstructedParticle represents inferred objects. The current AnaEvent name is an alias of DEvent. This separation matters physically: truth is useful for explaining a background, but an experimental selection must use measured or reconstructed quantities. Collection names also identify the detector region or response variant, so a change of input collection can change the meaning of a reconstructed energy even when the algorithm is unchanged. The event schema and output choices therefore belong in the production record.',2,55)
add('geometry-speed','Geometry and event-record optimisation',cols('<div class="eyebrow">Geometry navigation</div><h2 class="blue">Bounding volume hierarchy</h2><p class="small">Group detector volumes into nested bounding volumes to reduce navigation work.</p><div class="statline"><div><b>260 → 42</b><span>ms per event, without / with BVH</span></div></div><div class="big-number" style="margin-top:20px">6.2×</div><p class="small muted">Measured speed-up in the cited benchmark.</p>','<div class="eyebrow">Persistent event data</div><h2 class="gold">Record and memory layout</h2><p class="small">Optimise the stored data structure and memory alignment.</p><div class="statline"><div><b>60.1 → 13.7</b><span>KB per event, reported minimum</span></div></div><div class="big-number" style="margin-top:20px">4.4×</div><p class="small muted">Reduction for the cited event-record example.</p>')+take('Reduce work per transported event before increasing the scale of production.'),'Two optimisations address different costs. The bounding volume hierarchy groups detector volumes so Geant4 can reject larger spatial regions before testing individual cells. In the cited software benchmark the time changes from two hundred and sixty to forty-two milliseconds per event, a ratio of about six point two. Event-record optimisation and memory alignment reduce the reported example from sixty point one to a minimum of thirteen point seven kilobytes per event. This factor describes storage for that configuration, not every possible event record. These are historical benchmark results from the software presentation. They should not be multiplied with the optical benchmark or presented as measurements of a single frozen release.',2,65,source='DSS_716, slides 7 and 11. Ratios calculated from the reported values; benchmark configurations differ.')
add('staged-filter','Generator-level filtering with staged transport','<FlowDiagram kind="filter"/>'+take('Reject an event as soon as its production requirements fail, before transporting the full shower.'),'The generator-level filter acts during transport rather than waiting for a complete event on disk. At stage zero, only the primary track is urgent and its secondaries wait. This allows the primary interaction or energy-loss condition to be tested first. Stage one processes relevant secondaries in the region of interest, where the required rare interaction is checked. Only an accepted event releases the rest of the shower. An accumulated ECAL energy above an upper bound also permits early termination, since further deposits cannot bring the sum back down. The order of the decisions lets the simulation reject an event before processing secondaries that cannot affect its acceptance.',2,70)
add('biasing','Rare-process biasing and physical normalisation',cols('<h2 class="gold">Sample the rare interaction</h2><ul><li>Select the process and detector region</li><li>Enhance its interaction probability</li><li>Retain the relevant secondary ancestry</li><li>Apply production filters within a defined domain</li></ul>','<h2 class="blue">Recover the physical prediction</h2><div class="formula-band">'+L(r'\widehat N=\sum_{j\in\mathrm{sel}}w_j')+'</div><div class="formula-band">'+L(r'N_{\mathrm{eff}}=\frac{(\sum_jw_j)^2}{\sum_jw_j^2}')+'</div><p class="small">The positron campaign uses dedicated process-rate normalisations, rather than the stored transport-weight field.</p>')+take('Biasing increases sampling frequency. Filtering defines which phase space is retained.'),'Biasing increases the frequency of a selected rare interaction in a specified region. This is an importance-sampling operation, so the physical rate must be recovered with the normalisation appropriate to the sample. In generic weighted counting, the sum of weights gives the yield and the sum of squared weights gives its Monte Carlo variance. The effective event count can be substantially smaller than the number of stored events. The positron campaign uses dedicated biasing studies and process cross sections for normalisation rather than the stored transport-weight field. A filter has a different role: it removes phase space. No weight can restore events outside the generated support, so production cuts must remain compatible with the analysis.',2,65)
add('filter-performance','Filtering changes the production cost','''<div class="eyebrow">Historical production example: 4 GeV electrons, 10¹¹ incident events, 12,800 cores</div><table><tr><th>Metric</th><th>Without truth filter</th><th>With truth filter</th><th>Change</th></tr><tr><td>Elapsed time</td><td>~4 days</td><td class="gold">~15 hours</td><td>~6.4× shorter</td></tr><tr><td>Disk write rate</td><td>~9 GB/s</td><td class="blue">~0.23 GB/s</td><td>~39× lower</td></tr><tr><td>Total storage</td><td>~3 PB</td><td class="mint">~2.5 TB</td><td>~1,200× smaller</td></tr></table><div class="columns" style="margin-top:22px"><div><h2>General filters</h2><p class="small">Early ECAL-energy and missing-momentum vetoes.</p></div><div><h2>Process-specific filters</h2><p class="small">Particle or process requirements in selected volumes and energy intervals.</p></div></div>'''+take('The largest saving comes from avoiding events and information that the target analysis does not need.'),'This table illustrates the practical effect at production scale. For ten to the eleven four GeV incident electrons on twelve thousand eight hundred cores, the cited estimate changes from around four days to fifteen hours. The storage changes from roughly three petabytes to two point five terabytes, while the quoted disk write rate also falls. These approximate figures describe different resource measures and should be read independently. The general filters reject events with excessive visible energy or insufficient missing momentum. Dedicated filters additionally require the relevant particle or interaction. The filter is part of the sample definition, so the retained phase-space range and acceptance must accompany the output.',2,65,source='DSS_716, slide 13. Historical example; quoted values are approximate.')
add('parallelism','Parallel event simulation','''<div class="columns"><div><h2 class="blue">Geant4 multi-threading</h2><ul><li>G4MTRunManager</li><li>Thread-local allocators and singleton state</li><li>Thread-safe primary generation and random-number handling</li><li>Inclusive and rare-process validation</li></ul></div><div><table><tr><th>Configuration</th><th>Elapsed time</th><th>CPU usage</th></tr><tr><td>8 threads, 1 job</td><td class="gold">15,328 s</td><td>785%</td></tr><tr><td>1 thread, 8 jobs</td><td>16,648 s</td><td>646%</td></tr></table><div class="big-number" style="margin-top:25px">~8%</div><p class="small">Lower elapsed time for the reported multi-thread comparison.</p></div></div>'''+take('Parallelism complements reduced event cost and selective generation.'),'Geant4 multi-threading allows several events to be processed within one job. The engineering work includes thread-local allocation and singleton state, as well as random-number and primary-generation handling. In the cited comparison, one eight-thread job takes fifteen thousand three hundred and twenty-eight seconds, compared with sixteen thousand six hundred and forty-eight seconds for eight single-thread jobs. This is an improvement of approximately eight percent in elapsed time for that comparison. It is not a measurement of eight-fold scaling from one core. The validation includes inclusive and rare-process distributions. The physics content must remain consistent as the scheduling and number of workers change.',2,55,source='DSS_716, slide 15, INPAC cluster benchmark. Relative time reduction calculated from reported times.')
add('optical-lut','Optical response with a lookup table',cols(plot('lut-eff','LUT detection efficiency compared with full optical transport.','plot-large'),'<h2 class="mint">Precompute the expensive transport</h2><p class="small">Sample detection efficiency and transit time as functions of emission position and direction.</p><table><tr><th>Response path</th><th>Time/event</th></tr><tr><td>Full optical tracking</td><td>~200 s</td></tr><tr><td>LUT optical response</td><td class="gold">~4 s</td></tr><tr><td>No optical photons</td><td>~2 s</td></tr></table><p class="small">Efficiency agreement within 5% in the stated validation.</p>','wide')+take('About 50× faster than full optical tracking for the cited complete-event benchmark.'),'Full optical transport is expensive because a single interaction can generate a very large number of photons. The lookup table replaces repeated scintillation-photon propagation with a conditional response. It stores both a detection probability and a transit-time distribution. In the cited study, the full event takes about two hundred seconds with optical tracking, four seconds with the table, and two seconds without optical photons. The comparison on the left tests detection efficiency and agrees within five percent. This validates the table for the optical geometry and properties used to construct it. It does not automatically validate later electronics effects or a different detector geometry. The digitisation and optical studies are collaboration contributions integrated into the common framework.',2,65,source='DarkSHINE optical-response study. Single-core Intel Xeon E5-2680v4 benchmark.')
add('digitisation','Digitisation connects deposits to observables','<div style="height:145px;overflow:hidden"><FlowDiagram kind="digit" style="height:145px;margin-top:-3px"/></div>'+cols('<h2 class="violet">Response effects</h2><p class="small">Scintillation, collection efficiency, SiPM saturation and recovery, electronic noise, finite dynamic range and ADC sampling.</p><p class="small muted">Detailed optical and parameterised response paths serve different production needs.</p>',plot('waveform','Digitised signals in representative ECAL cells.','plot-short'))+take('The selected response collection and calibration define the meaning of reconstructed cell energy.'),'The digitisation chain turns transported energy into the quantities that reconstruction uses. Light production and collection determine how many photons reach the sensor. The SiPM response includes finite pixel occupancy and recovery. Electronics then add the waveform, noise, finite range and digitisation. The framework also provides a parameterised response for campaigns that do not need full optical information. These paths should not be conflated. A response model available in the software is not necessarily enabled in a particular physics sample. Since the positron selection uses both total energy and maximum-cell energy, the per-cell response and its threshold behaviour are especially important.',2,60,source='DarkSHINE digitisation and waveform study; collaboration contribution.')
add('tracking','Track finding and fitting','<div style="height:190px"><FlowDiagram kind="tracking" style="height:190px"/></div>'+cols('<h2 class="blue">Finding</h2><p class="small">Associate hits across tracker layers.<br/>The legacy greedy finder ranks circle candidates and removes accepted hits.</p>','<h2 class="gold">Fitting</h2><p class="small">Estimate momentum and covariance with magnetic-field propagation, energy loss and multiple scattering.</p><p class="small muted">GenFit Kalman fitting and a Riemann alternative are available.</p>')+take('Momentum residuals must compare reconstructed and reference states at the same surface.'),'Track finding and fitting are distinct tasks. Finding determines which hits belong together. The low-multiplicity legacy algorithm uses a fast circle pre-fit to rank candidates and removes accepted hits before finding the next track. Fitting then refines the track parameters with a model of the magnetic field, material and measurement errors. A circle-ranking score is not a complete track-fit likelihood. The framework supports GenFit-based Kalman fitting and an analytical Riemann alternative. To assess momentum resolution, the fitted state and the reference state must be compared at the same surface. This also matters when comparing tagging and recoil momenta across the target.',2,55)
add('acts','ACTS integration in DarkSHINE','<FlowDiagram kind="acts"/>'+take('The independent sequencer uses truth-smeared seeds in its reference configuration.'),'My ACTS integration provides an independent sequencer as well as optional adapters in the existing Tracking processor. The sequencer converts detector information into tracking surfaces and transforms strip-pair hits into ACTS measurements and source links. Geometry, momentum and field vectors use one consistent coordinate mapping. The reference chain starts with truth-smeared seeds, runs combinatorial Kalman track finding, converts the trajectories and performs vertex finding. Extrapolated recoil tracks can seed ECAL clustering. This is an integration and reconstruction study, not a measurement of fully hit-based seeding efficiency. The alternative space-point route requires completion and validation, and the later ACTS developments should not be attributed to the frozen positron-analysis production.',2,70,source='Candidate contribution: ACTS sequencer, geometry/field adapters and reconstruction interfaces.')
add('generator-validation','Signal generation and validation',cols(plot('generator-comparison','External and transport-native signal-generation comparison.','plot-large'),'<h2 class="blue">Two connected routes</h2><p>External hard-process generation supplies signal kinematics.</p><p>A Geant4-native process supports transport-based production.</p><div class="rule"></div><h2 class="gold">Checks at several levels</h2><p class="small">Total cross section, recoil energy, angle and transverse momentum.</p><p class="small muted">Agreement of rates and agreement of shapes test different inputs.</p>','wide')+take('A common configuration and normalisation are required before comparing generator predictions.'),'The software supports external hard-process kinematics and a transport-native dark-photon process. The external route uses matrix-element generators and passes the resulting particles into detector transport. The native route integrates production with Geant4. Generator validation checks the cross section and several recoil distributions. Comparing only the integrated cross section would miss a kinematic disagreement that changes detector acceptance. Conversely, normalised shape agreement does not establish the absolute rate. The beam, target, mass, coupling convention and generation cuts must match in a meaningful comparison. These validation studies are collaboration results that establish the interfaces used by the framework and analysis.',2,60,source='DarkSHINE signal-generator comparison; collaboration study. Original plot retained.')
chapter('positron','Positron-Beam-Mode<br/>Analysis','atom',3,'Three production mechanisms, three exclusive reconstructed categories','I now use the simulation chain to evaluate the positron option. The analysis retains the baseline one detector for a common comparison with the published electron-beam projection.')
add('cross-sections','Production mechanisms at 8 GeV',cols(plot('xsections','Production cross sections divided by kinetic mixing squared.','plot-large'),'<h2 class="gold">Annihilation adds a mass scale</h2><div class="formula-band">'+L(r's=2m_e(E_{e^+}+m_e)')+'</div><p>For an electron at rest,</p><div class="big-number">'+L(r'\sqrt{s}=90.4\,\mathrm{MeV}')+'</div><p class="small">Bound-electron motion broadens the stationary-electron picture.</p><p class="small muted">The projection uses on-shell signal samples.</p>','wide')+take('The radiative endpoint and resonant enhancement motivate a detector-level comparison near 90 MeV.'),'The production curves show why the positron mode is interesting. Nuclear bremsstrahlung remains available over a broad mediator-mass range. Non-resonant annihilation is kinematically limited by the centre-of-mass energy, and resonant production is enhanced around the corresponding scale. For an eight GeV positron annihilating with a stationary electron, this is ninety point four MeV. Motion of bound electrons broadens that ideal picture, and the resonant samples extend beyond the stationary value. This study uses on-shell mediator samples rather than a separate off-shell dark-matter-pair calculation. The next step is to ask how much of each production mechanism survives the actual detector selection.',3,70,source='X. Zhu et al., arXiv:2609.05900. Original cross-section plot.')
add('samples','Signal and background samples',cols('<h2 class="blue">Signal grid</h2><table><tr><th>Mechanism</th><th>Mass points</th></tr><tr><td>Dark bremsstrahlung</td><td>30</td></tr><tr><td>Non-resonant annihilation</td><td>18</td></tr><tr><td>Resonant annihilation</td><td>23</td></tr></table><p class="small">'+L(r'10^5')+' events per channel–mass point.</p><p class="small">CalcHEP kinematics followed by Geant4 transport.</p>','<h2 class="gold">Background production</h2><ul class="small"><li>PN, EN and muon-pair conversion</li><li>Target/tracker and ECAL locations</li><li>Additional target-annihilation sample</li><li>Independent inclusive sample: '+L(r'2.5\times10^9')+' POT</li></ul><div class="rule"></div><p class="small">Common benchmark: 8 GeV, '+L(r'3\times10^{14}')+' POT, baseline 1 detector.</p>')+take('Equal generated signal counts measure efficiency. Cross sections determine the physical mixture.'),'The signal grid contains thirty bremsstrahlung masses, eighteen non-resonant masses and twenty-three resonant masses, with one hundred thousand generated events at each point. Equal sample sizes separate the efficiency calculation from the relative physical rates. Background production uses dedicated biased samples for photonuclear, positron-nuclear and muon-pair processes, with target or tracker production separated from ECAL production. The retained EN label denotes the positron-nuclear sample in this campaign. An additional target-annihilation sample accounts for ordinary annihilation topologies. The independent inclusive sample represents two point five billion incident positrons and is used for cross-checking, rather than added to the dedicated predictions. All sensitivity results use baseline one.',3,65,source='Positron campaign sample definitions and mass grids; arXiv:2609.05900.')
add('signal-regions','Three exclusive signal regions','''<table class="selection-table"><tr><th>Selection</th><th class="blue">SR1: recoil positron</th><th class="gold">SR2: photon-like</th><th class="rose">SR3: low activity</th></tr><tr><td>Tagging tracks</td><td>= 1</td><td>= 1</td><td>= 1</td></tr><tr><td>Recoil tracks</td><td class="blue">= 1</td><td class="gold">= 0</td><td class="rose">= 0</td></tr><tr><td>'''+L(r'P_{\rm tag}-P_{\rm rec}')+'''</td><td>&gt; 4 GeV</td><td>—</td><td>—</td></tr><tr><td>ECAL total energy</td><td>&lt; 2.5 GeV</td><td>&lt; 2 GeV</td><td>&lt; 2 GeV</td></tr><tr><td>ECAL maximum cell</td><td>—</td><td class="gold">≥ 1 MeV</td><td class="rose">&lt; 1 MeV</td></tr><tr><td>HCAL total energy</td><td>&lt; 100 MeV</td><td>&lt; 100 MeV</td><td>&lt; 100 MeV</td></tr><tr><td>HCAL maximum cell</td><td>&lt; 1 MeV</td><td>&lt; 1 MeV</td><td>&lt; 1 MeV</td></tr></table>'''+take('Track multiplicity separates SR1. Complementary ECAL maximum-cell cuts separate SR2 and SR3.'),'These selections define reconstructed categories independently of the generated process. Every category requires exactly one tagging track. SR1 has one recoil track and a scalar tagging-minus-recoil momentum difference above four GeV. SR2 and SR3 have zero recoil tracks. Their total ECAL energy must be below two GeV, and complementary maximum-cell conditions divide the samples at one MeV. An event at the boundary enters SR2. Every region also requires low total HCAL energy and no cell above one MeV. Consequently an event can enter at most one region. The regions do not cover all events: additional tracks or failure of any veto removes the event from the analysis.',3,90,source='Fixed working points for the baseline 1 positron projection.')
add('kinematic-selection','Momentum and total-energy discrimination',cols(plot('missing-p','Scalar tagging-to-recoil momentum difference in SR1.','plot-large'),plot('ecal-ann','Total ECAL energy for non-resonant annihilation.','plot-large'))+take('The production filter uses '+L(r'\Delta P>1\,\mathrm{GeV}')+'. The final SR1 requirement is '+L(r'\Delta P>4\,\mathrm{GeV}')+'.'),'The left panel shows the tagging-to-recoil momentum difference for the recoil topology. The background curve already satisfies the loose production filter at one GeV, while the final analysis uses four GeV. Confusing those two thresholds would misstate the signal region. The right panel shows total ECAL energy for the non-resonant channel. Near the mediator endpoint, the accompanying photon becomes soft and the ninety MeV signal can satisfy a low visible-energy condition. This is why an annihilation process with a photon can still improve a missing-energy search. The detector response and acceptance determine the selected distribution, so the cut cannot be understood from the production rate alone.',3,65,source='Original detector-level distributions; arXiv:2609.05900.')
add('maximum-cell','Maximum-cell energy separates the zero-track sample',cols(plot('cell-ann','Non-resonant annihilation: photon deposit depends on mediator mass.','plot-large'),plot('cell-res','Resonant annihilation: predominantly very low ECAL activity.','plot-large'))+take(L(r'E_{\mathrm{ECAL}}^{\mathrm{MaxCell}}\geq1\,\mathrm{MeV}')+' defines SR2; '+L(r'E_{\mathrm{ECAL}}^{\mathrm{MaxCell}}<1\,\mathrm{MeV}')+' defines SR3.'),'Within the zero-recoil-track sample, the largest ECAL cell distinguishes a photon-like deposit from a nearly empty calorimeter. The non-resonant channel changes with mass because the photon kinematics change. Resonant annihilation mostly produces low activity, though interactions in tracking material can leave deposits. The total-energy requirement remains necessary in addition to the largest-cell condition: many small deposits can have a sizeable sum. The one MeV values are selection thresholds, not measured noise levels. In particular, the HCAL noise and pileup response is not fully digitised in this prospective campaign, so the HCAL threshold must be treated as an assumed achievable performance.',3,60,source='Original maximum-cell distributions; threshold interpretation follows the production assumptions.')
add('efficiency','Signal efficiency across the mass scan','<div class="columns thirds">'+''.join('<div>'+plot(k,c,'plot-mid')+'</div>' for k,c in [('efficiency_brem_bremCut','Bremsstrahlung → SR1'),('efficiency_tch_tchCut','Non-resonant annihilation → SR2'),('efficiency_sch_schCut','Resonant annihilation → SR3')])+'</div><div class="formula-band">'+L(r'\eta_{ic}=\frac{N_{\mathrm{selected\ in\ SR}\ i,c}}{N_{\mathrm{generated},c}}')+'</div>'+take('All nine channel-to-region efficiencies enter the signal prediction.'),'The three panels show the cutflow efficiency of each mechanism in its primary region. Each curve uses its own generated channel and mass as the denominator, so these are selection fractions rather than a physical mixture. All nine channel-to-region curves are included in the separate backup booklet. The expected visible remnant may be lost: a recoil can fail reconstruction, and a photon can escape acceptance or remain below threshold. Such events can migrate into another signal region and remain useful. For example, bremsstrahlung contributes to zero-track regions, with substantial low-activity efficiency toward the upper end of its mass grid. The complete response matrix is therefore needed.',3,70,source='Channel-to-region efficiencies from the baseline 1 positron simulation.')
add('migration','Migration contributes to the selected signal','''<div class="eyebrow">Benchmark: '''+L(r'm_{A^{\prime}}=90\,\mathrm{MeV},\quad\epsilon^2=10^{-12},\quad3\times10^{14}\ \mathrm{POT}')+'''</div><table><tr><th>Generated mechanism</th><th>Produced</th><th>SR1</th><th>SR2</th><th>SR3</th></tr><tr><td>Dark bremsstrahlung</td><td>0.00137</td><td>0.000850</td><td>0.000111</td><td>0.000142</td></tr><tr><td>Non-resonant annihilation</td><td>1.96</td><td>0.0389</td><td class="gold">1.74</td><td>0.114</td></tr><tr><td>Resonant annihilation</td><td>0.705</td><td>0.00156</td><td>0.0870</td><td class="rose">0.601</td></tr><tr><td><strong>Total</strong></td><td>2.67</td><td>0.0413</td><td class="gold">1.82</td><td class="rose">0.715</td></tr></table><div class="formula-band">'''+L(r's_i(m)=\sum_c N_{\mathrm{prod},c}(m)\,\eta_{ic}(m)')+'''</div>'''+take('A signal-region label specifies an observed topology, not a unique production mechanism.'),'At ninety MeV the table makes the migration explicit. Non-resonant annihilation produces about one point nine six events at the illustrative kinetic mixing and contributes primarily to SR2, but it also populates SR1 and SR3. Resonant production mostly enters SR3 and also contributes to SR2. The small bremsstrahlung yield is retained in every category. Summing the contributions gives approximately zero point zero four events in SR1, one point eight two in SR2 and zero point seven one five in SR3. The likelihood uses the individual region predictions. It does not assign an observed candidate to a generator-level origin. Totals are calculated before rounding.',3,70,source='Benchmark yields at fixed coupling, reproduced from the positron study; totals rounded independently.')
add('rejection','Background rejection in the available simulation','''<div class="eyebrow">PN ECAL example: cumulative, unweighted simulated counts</div><table><tr><th>Selection stage</th><th>SR1</th><th>SR2</th><th>SR3</th></tr><tr><td>One tagging track</td><td>5,794,358</td><td>5,794,358</td><td>5,794,358</td></tr><tr><td>Recoil category</td><td>4,641,895</td><td>138,513</td><td>138,513</td></tr><tr><td>Topology-specific pre-veto cut</td><td>3,114,535</td><td>138,513</td><td>120,147</td></tr><tr><td>HCAL total-energy veto</td><td>272,207</td><td>8,051</td><td>3,922</td></tr><tr><td>HCAL maximum-cell veto</td><td>88,871</td><td>2,552</td><td>1,096</td></tr><tr><td>Final ECAL requirement</td><td class="gold">0</td><td class="gold">0</td><td class="gold">0</td></tr></table><p class="tiny muted">Pre-veto cut: momentum in SR1; ECAL maximum-cell lower bound in SR2; ECAL total energy in SR3.</p>'''+take('Zero simulated survivors establish rejection in the sample. Residual physical rates require an extrapolation.'),'The cumulative cutflow shows where rejection occurs in one important background, photonuclear production in the ECAL. The recoil requirement already separates the one-track and zero-track categories. Their next cuts differ: momentum for SR1, the maximum-cell lower bound for SR2 and total ECAL energy for SR3. The HCAL veto then reduces the sample further, and the final ECAL condition removes all remaining simulated events. These are unweighted counts, not yields at the benchmark exposure. No inclusive or dedicated sample survives a complete region selection. This is strong rejection in the available simulation, but it is not evidence that the physical background is exactly zero.',3,65,source='Cumulative PN ECAL cutflow from the positron study. Effective exposure: 1.48×10¹¹ POT.')
add('background-validation','Normalisation checked in populated sidebands',cols(plot('validation','Dedicated rare-process sum compared with inclusive production.','plot-large'),'<h2 class="blue">Independent comparison</h2><p class="small">Dedicated samples are normalised using process rates and filter acceptance.</p><p class="small">The inclusive sample tests the populated survival trend.</p><div class="formula-band" style="font-size:19px">'+L(r'N_{\mathrm{POT}}^{\mathrm{eff}}=\frac{N_{\mathrm{attempt}}\epsilon_{\mathrm{gen}}}{\mathcal B}')+'</div><p class="small muted">The two routes describe the same backgrounds and are not added together.</p>','wide')+take('Sideband agreement supports the production model where simulated events remain.'),'The dedicated samples are normalised to their equivalent unbiased exposure using the generation attempts, generator acceptance and physical branching ratio. This convention distinguishes attempts from stored events. After normalisation, their sum can be compared with an unbiased inclusive sample in the populated region. Target annihilation is included in this check. Agreement tests the rates and distributions where there are simulated events. It cannot directly test the much smaller tail probability at the final working points. Since inclusive and dedicated routes represent the same physical processes, combining them by simply adding their yields would double count the background.',3,65,source='Inclusive exposure: 2.5×10⁹ POT. Dedicated sample normalisation follows the campaign convention.')
add('background-tail','Residual-background extrapolation','<div class="columns"><div>'+plot('sr1-tail','SR1: dedicated PN ECAL survival fit.','plot-short')+'</div><div>'+plot('sr3-tail','SR3: joint ECAL survival surface.','plot-short')+'</div></div><table class="compact-table"><tr><th>Region</th><th>Tail construction</th><th>Nominal events</th></tr><tr><td>SR1</td><td>EN + PN, total ECAL threshold</td><td class="blue">0.03</td></tr><tr><td>SR2</td><td>PN, total ECAL threshold</td><td class="gold">1.3×10⁻⁴</td></tr><tr><td>SR3</td><td>PN, two ECAL thresholds</td><td class="rose">1.6×10⁻⁴</td></tr></table>'+take('The nominal backgrounds rely on continuation from populated sidebands into empty tails.'),'For SR1 and SR2 the dedicated survival curves are fitted as a power law in the numerical total-ECAL threshold in MeV. The resulting nominal backgrounds are zero point zero three events for SR1 and one point three times ten to the minus four for SR2. SR3 needs a two-dimensional continuation because the total and maximum-cell energies are related. Its nominal yield is one point six times ten to the minus four. These are extrapolated predictions. Fit-function dependence, limited tail statistics and components omitted after zero survivors remain limitations. The inclusive one-dimensional comparison uses a different exponential form and does not establish quantitative closure at the final thresholds.',3,75,source='Dedicated tail estimates at 3×10¹⁴ POT. SR3 surface is a fit, not a selection boundary.')
add('likelihood','Combined statistical interpretation','<div class="formula-band" style="font-size:27px">'+L(r's_i=\sum_cN_{\mathrm{prod},c}\eta_{ic},\qquad\mu\simeq\frac{\epsilon^2}{\epsilon_{\mathrm{ref}}^2}')+'</div>'+cols('<h2 class="blue">Joint region model</h2><ul><li>Three mutually exclusive signal regions</li><li>One signal strength for all mechanisms</li><li>All channel-to-region migrations retained</li><li>Profile nuisance parameters in the fit</li></ul>','<h2 class="gold">Expected 90% CL limits</h2><p class="small">Background-only expectation using '+L(r'\mathrm{CL}_s')+' and asymptotic profile likelihood.</p><div class="formula-band" style="font-size:22px">'+L(r'\lambda(\mu)=\frac{\mathcal L(\mu,\hat{\hat{\theta}}_\mu)}{\mathcal L(\hat\mu,\hat\theta)}')+'</div><p class="small muted">Background-shape uncertainties are uncorrelated between bins in the reported construction.</p>')+take('The very-low-background asymptotic approximation still needs validation with pseudo-experiments.'),'At each mass the signal prediction sums all three production mechanisms in every region. One common signal strength scales those contributions because the same kinetic mixing controls their rates. The analysis uses a binned profile likelihood with nuisance parameters and obtains expected ninety-percent confidence-level limits with CLs under the background-only hypothesis. Shape uncertainties are treated as uncorrelated between bins in the reported construction, and the background normalisation uses its stated Poisson prescription. Region exclusivity prevents double counting of events but does not by itself imply that detector uncertainties are independent. The asymptotic method is used well below one expected background event, and its coverage has not yet been checked with pseudo-experiments.',3,70,source='Statistical prescription reported in arXiv:2609.05900; limitations retained.')
add('mode-results','Annihilation drives the gain near 90 MeV',cols(plot('modes','Each individual-mechanism fit still uses all three signal regions.','plot-large'),'<h2 class="gold">At '+L(r'm_{A^{\prime}}=90\,\mathrm{MeV}')+'</h2><table class="compact-table"><tr><th>Mechanism</th><th>'+L(r'\epsilon^2_{90}')+'</th></tr><tr><td>Bremsstrahlung</td><td>'+L(r'1.34\times10^{-9}')+'</td></tr><tr><td>Non-resonant</td><td>'+L(r'7.29\times10^{-13}')+'</td></tr><tr><td>Resonant</td><td>'+L(r'1.97\times10^{-12}')+'</td></tr><tr><td><strong>Combined</strong></td><td class="gold">'+L(r'5.33\times10^{-13}')+'</td></tr></table><p class="small">Non-resonant annihilation gives the strongest individual projected limit at this mass.</p>','wide')+take('The radiative endpoint contribution is essential to the combined result.'),'This comparison retains one production mechanism at a time while keeping all three measured regions and the same background model. It therefore includes migration even in the individual curves. At ninety MeV, non-resonant annihilation gives the strongest individual projected limit, about seven point three times ten to the minus thirteen in epsilon squared. Resonant annihilation also contributes, and the combination reaches five point three three times ten to the minus thirteen. It would be misleading to attribute the entire improvement simply to the resonant channel. The radiative endpoint and the detector efficiency of the associated photon category make a major contribution.',3,75,source='Expected 90% CL projection at 3×10¹⁴ POT; original mechanism-comparison plot.')
add('reach','Projected reach in mediator mass and kinetic mixing',cols(plot('limits','Expected positron reach compared with electron running and other searches.','fullplot'),'<div class="eyebrow">8 GeV, baseline 1</div><div class="big-number">'+L(r'5.33\times10^{-13}')+'</div><p>'+L(r'\epsilon^2')+' at '+L(r'm_{A^{\prime}}=90\,\mathrm{MeV}')+'</p><div class="rule"></div><p class="small">About two orders of magnitude stronger than the earlier electron projection near this mass at matched exposure.</p><p class="small muted">Expected sensitivity under the stated background and veto assumptions.</p>','wide'),'The full comparison places the combined positron projection alongside the earlier electron-beam projection and external constraints and prospects. Near ninety MeV the gain is about two orders of magnitude in epsilon squared at matching integrated luminosity. The sharp feature follows the annihilation kinematics; it is not a uniform improvement over the entire mass range. At lower masses bremsstrahlung remains relevant. Existing exclusions and future projections have different experimental status even when they are drawn on the same plane. This result is a prospective detector-level study under a specified exposure, baseline detector and background model, rather than an observed exclusion.',3,80,source='Original comparison figure from the positron study; external curves retain source assumptions and exposure labels.')
add('thermal','Interpretation relative to thermal targets',cols(plot('dm-limits','Thermal targets for the stated dark-sector benchmark.','fullplot'),'<h2 class="gold">Additional model assumptions</h2><p>'+L(r'm_{A^{\prime}}=3m_\chi')+'</p><p>'+L(r'\alpha_D=0.5')+'</p><div class="formula-band" style="font-size:20px">'+L(r'y=\epsilon^2\alpha_D\left(\frac{m_\chi}{m_{A^{\prime}}}\right)^4')+'</div><p class="small">Then '+L(r'y=\epsilon^2/162')+'.</p><p class="small">The 90 MeV mediator scale corresponds to '+L(r'm_\chi=30\,\mathrm{MeV}')+'.</p><p class="small muted">Thermal curves retain their spin and annihilation assumptions.</p>','wide'),'To relate the mediator search to light-dark-matter thermal targets, I now add a mass ratio of three and a dark coupling alpha D of zero point five. These assumptions define the vertical variable y and map a ninety MeV mediator to a thirty MeV dark-matter particle. For this benchmark y is epsilon squared divided by one hundred and sixty-two. The transformation changes the coordinates, not the simulated event categories or efficiency. Scalar, Majorana and pseudo-Dirac thermal targets depend on their own spin and annihilation assumptions. The result tests those specified benchmarks. It should not be interpreted as a universal exclusion of every dark-sector model at the same mass.',3,65,source='Original thermal-target plot with mA′/mχ=3 and αD=0.5.')
add('scope','Scope of the positron projection',cols('<h2 class="blue">Established within this study</h2><ul><li>Full detector-level signal efficiencies</li><li>Three exclusive categories with migration</li><li>Dedicated and inclusive sideband comparison</li><li>A combined 8 GeV benchmark projection</li></ul>','<h2 class="gold">Inputs requiring further validation</h2><ul><li>Background extrapolation into empty tails</li><li>Rare components omitted after zero survivors</li><li>1 MeV HCAL cell threshold with noise and pileup</li><li>Low-count coverage of the asymptotic likelihood</li></ul>')+take('The gain is conditional on the production, detector-response and statistical assumptions.'),'The analysis establishes the detector-level efficiency and migration of the three mechanisms for the benchmark setup, and it connects them to exclusive reconstructed categories and a combined projection. The main limitations lie in the very small background tails and in the assumed veto response. Larger rare-process samples are needed to constrain extrapolation and omitted components. Prototype measurements must establish threshold performance with realistic noise and pileup. Pseudo-experiments are needed to test the low-count statistical construction. These are distinct validation tasks: success in one does not establish the others. Keeping them explicit defines what is needed to turn the prospective sensitivity into an experimentally supported search.',3,60)
chapter('summary','Summary and Outlook','detector',4,'Simulation infrastructure and a prospective positron search','I close by connecting the software and physics results and identifying the next steps.')
add('conclusions','Main results',cols('<div class="eyebrow">Simulation framework</div><h2 class="blue">A common event-processing chain</h2><p>Configurable transport and DEvent interfaces connect detector studies to reconstruction and analysis.</p><p class="small">Geometry optimisation, staged filters, biasing and parallel execution make rare-process production practical.</p><p class="small">ACTS interfaces support tracking and calorimeter matching.</p>','<div class="eyebrow">Positron-beam mode</div><h2 class="gold">Additional annihilation channels</h2><p>Three exclusive signal regions retain all production-to-category migrations.</p><div class="big-number" style="font-size:36px;margin-top:20px">'+L(r'\epsilon^2=5.33\times10^{-13}')+'</div><p class="small">Expected 90% CL reach at 90 MeV and '+L(r'3\times10^{14}')+' POT.</p>')+take('The framework provides the connection between detector assumptions and the projected physics reach.'),'The software result is a configurable framework and event model that connect transport, detector response and reconstructed observables. Geometry and record optimisation reduce per-event cost; biasing and staged filters focus resources on rare backgrounds; parallel execution increases production capacity. ACTS integration extends the reconstruction environment. The physics result is a prospective positron search with three exclusive categories and all migrations retained. At ninety MeV, the combined expected limit reaches five point three three times ten to the minus thirteen in epsilon squared at the benchmark exposure. The improvement is driven by annihilation, particularly the non-resonant contribution near its endpoint, under the assumptions already discussed.',4,65)
add('outlook','Outlook','''<div class="timeline"><div><b>Detector response</b><p>Constrain digitisation, calibration and veto thresholds with prototype and beam-test data.</p></div><div><b>Rare backgrounds</b><p>Extend dedicated samples and quantify the stability of sideband extrapolations.</p></div><div><b>Statistical model</b><p>Validate the low-count limit with pseudo-experiments and explicit modelling uncertainties.</p></div><div><b>Beam-energy scan</b><p>Re-evaluate signal, acceptance and backgrounds at additional positron energies.</p></div></div><div class="formula-band" style="margin-top:33px">'''+L(r'm_{A^{\prime}}^{\mathrm{ann}}\sim\sqrt{2m_eE_{e^+}}')+'</div>'+take('Changing the beam energy moves the annihilation scale and motivates further detector-level studies.'),'The next work follows directly from the limitations. Detector data can constrain the response and veto thresholds. Larger rare-process samples can support the tails and help quantify model dependence. Pseudo-experiments can test the statistical approximation where expected backgrounds are extremely small. Finally, varying the beam energy moves the characteristic annihilation mass approximately with the square root of the energy. This suggests a way to investigate other masses, but each energy needs its own kinematics, acceptance and background study. The present result establishes the eight GeV benchmark and supplies a framework in which those extensions can be carried out.',4,55)
add('achievements','Research Achievements','''<div class="achievements"><div><div class="eyebrow">Lead-author work</div><div class="achievement highlight"><strong>Xuliang Zhu et al.<br/>Prospective study of light dark matter search in positron beam mode with DarkSHINE experiment initiative</strong><span>arXiv:2609.05900 (2026). Accepted by Frontiers of Physics.</span></div><div class="achievement highlight"><strong>Xuliang Zhu<br/>DarkSHINE Simulation software framework</strong><span>Nucl. Part. Phys. Proc. 346 (2024) 57.<br/>DOI: 10.1016/j.nuclphysbps.2024.07.003</span></div><div class="achievement"><strong>DarkSHINE simulation and reconstruction software</strong><span>Co-author. Manuscript in preparation.</span></div><div class="achievement"><strong>DarkSHINE Baseline Design Report</strong><span>Collaboration contribution. Version 2, preliminary.</span></div></div><div><div class="eyebrow">Co-authored publications</div><div class="achievement"><strong>Electroweak phase transition at CEPC via exotic Higgs decays with 4b final states</strong><span>Z. Wang, X. Zhu et al. LHEP (2023) 436.</span></div><div class="achievement"><strong>Prospective light-dark-matter search with DarkSHINE</strong><span>J. Chen et al. Sci. China Phys. Mech. Astron. 66 (2023) 211062.</span></div><div class="achievement"><strong>LYSO crystal electromagnetic calorimeter design</strong><span>Z.-Y. Zhao et al. Nucl. Sci. Tech. 36 (2025) 41.</span></div><div class="achievement"><strong>Hadronic calorimeter design for DarkSHINE</strong><span>Z. Wang et al. Nucl. Sci. Tech. 35 (2024) 148.</span></div></div></div><div class="takeaway" style="font-size:21px;color:#f0c36e">Thank you for your attention</div>''','These are the research achievements listed in my dissertation. The first two entries are my lead-author works on the positron study and the simulation framework. The remaining publications and reports are collaborative contributions, including the CEPC exotic-Higgs study, DarkSHINE physics prospects and calorimeter design. The simulation and reconstruction manuscript remains in preparation, and the baseline design report is preliminary. Thank you for your attention. I welcome your questions.',4,45,source='Publication status reproduced from the supplied List of Research Achievements.')
